function Assert([bool]$ok,[string]$message){if(-not$ok){throw "Assertion failed: $message"}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function WaitTask($task,[int]$timeout=30000){$watch=[Diagnostics.Stopwatch]::StartNew();while(-not$task.IsCompleted-and$watch.ElapsedMilliseconds-lt$timeout){Pump 20};if(-not$task.IsCompleted){throw 'Task timeout'};if($task.IsFaulted){throw $task.Exception.InnerException}}
function ImageFile([string]$path,[Drawing.Color]$color){$dir=[IO.Path]::GetDirectoryName($path);[IO.Directory]::CreateDirectory($dir)|Out-Null;$b=[Drawing.Bitmap]::new(160,110);$g=[Drawing.Graphics]::FromImage($b);try{$g.Clear($color);$g.FillEllipse([Drawing.Brushes]::White,25,20,80,60);$b.Save($path)}finally{$g.Dispose();$b.Dispose()}}
function Contour([double]$length){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]@([double]0,0),[HalconDotNet.HTuple]@([double]0,$length));$x}
function MultiXld([double[]]$lengths){[HalconDotNet.HObject]$all=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$all);foreach($length in $lengths){$one=Contour $length;[HalconDotNet.HObject]$combined=$null;try{[HalconDotNet.HOperatorSet]::ConcatObj($all,$one,[ref]$combined);$all.Dispose();$all=$combined;$combined=$null}finally{$one.Dispose();if($null-ne$combined){$combined.Dispose()}}};$all}

$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s44-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadata=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true);$storeType=$assembly.GetType('HalconWinFormsDemo.Services.BatchTraceStore',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public';$arg=New-Object 'object[]' 1;$arg[0]=$temp.ToString();$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke($arg);$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke($arg);$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$field=$main.GetField($name,$all);if($null-eq$field){throw "Missing field $name"};$field.GetValue($window)}
$flow=$main.GetField('flowTools',$private).GetValue($window);$create=$main.GetMethod('CreateFlowTool',$private);$runClass=$main.GetMethod('RunXldLengthClassificationTool',$private);$execute=$main.GetMethod('ExecuteFlowTool',$private);$dispose=$main.GetMethod('DisposeFlowTools',$private);$capture=$main.GetMethod('CaptureRecipe',$private);$applyRecipe=$main.GetMethod('ApplyRecipe',$private)
function Tool([string]$kind,[string]$name){$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function RunClass($tool,$xld){try{$runClass.Invoke($window,[object[]]@($tool,$xld))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value}

# UI and typed port contract.
foreach($name in @('BatchTraceTab','BatchTraceGrid','BatchTraceItemGrid','BatchTraceFromDatePicker','BatchTraceToDatePicker','BatchTraceIdFilterTextBox','BatchTraceRecipeFilterTextBox','BatchTraceResultFilterComboBox','BatchTraceSummaryText','ProductionBatchTraceGrid','DockXldLengthClassificationPanel','DockXldLengthShortMaximumTextBox','DockXldLengthMediumMaximumTextBox')){Assert($null-ne(F $name)) "$name missing"}
$classKind=[Enum]::Parse($kindType,'XldLengthClassification');$inputs=$metadata.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($classKind));$outputs=$metadata.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($classKind));Assert(($inputs|Where-Object{$_.PortName-eq'XLD'-and$_.DataType-eq'XLD'-and-not$_.IsOptional}).Count-eq1) 'Required typed XLD input missing';foreach($port in @('ShortXLD','MediumXLD','LongXLD','ShortCount','ShortTotalLength','ShortMinLength','ShortMaxLength','ShortMeanLength','MediumCount','MediumTotalLength','MediumMinLength','MediumMaxLength','MediumMeanLength','LongCount','LongTotalLength','LongMinLength','LongMaxLength','LongMeanLength','ShortMaximum','MediumMaximum','Parameters','ResultCode')){Assert(($outputs|Where-Object PortName -eq $port).Count-eq1) "Output $port missing"}

$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.Width=1760;$window.Height=980;$window.Show();Pump 200

# A: real batch persistence, duplicate names, corrupt image isolation, cross-reload, shared development/production source, old fields, corrupt trace and CSV.
$p1=Join-Path $temp 'a\same.png';$p2=Join-Path $temp 'b\same.png';$bad=Join-Path $temp 'b\broken.png';ImageFile $p1 ([Drawing.Color]::DarkBlue);ImageFile $p2 ([Drawing.Color]::DarkGreen);[IO.File]::WriteAllText($bad,'not-an-image')
$dispose.Invoke($window,@())|Out-Null;$flow.Clear();$threshold=Tool ImageThreshold 'S44 Batch Threshold';$threshold.Parameters.ImageThresholdMinGray=0;$threshold.Parameters.ImageThresholdMaxGray=255;$flow.Add($threshold)
$load=$main.GetMethods($private)|Where-Object{$_.Name-eq'LoadImageQueue'-and$_.GetParameters().Count-eq1}|Select-Object -First 1;$load.Invoke($window,[object[]]@(,[string[]]@($p1,$p2,$bad)))|Out-Null;(F 'ImageQueueRunScopeComboBox').SelectedIndex=2;(F 'StopOnNgCheckBox').IsChecked=$false;(F 'ContinuousIntervalTextBox').Text='50';(F 'RecipeNameEditTextBox').Text='S44 Trace Recipe'
WaitTask ($main.GetMethod('RunImageQueueBatchAsync',$private).Invoke($window,@()))
$records=$main.GetField('batchTraceRecords',$private).GetValue($window);Assert($records.Count-eq1) 'Completed batch was not added to persistent history';$trace=$records[0];Assert($trace.RecipeName-eq'S44 Trace Recipe'-and$trace.RecipeFingerprint.Length-eq64) 'Recipe name/fingerprint missing';Assert($trace.TotalCount-eq3-and$trace.OkCount-eq2-and$trace.ErrorCount-eq1) 'Batch summary persistence mismatch';Assert(($trace.Items|Where-Object FileName -eq 'same.png').Count-eq2) 'Duplicate filenames were not preserved as distinct paths';$devSource=(F 'BatchTraceGrid').ItemsSource;$productionSource=(F 'ProductionBatchTraceGrid').ItemsSource;Assert([object]::ReferenceEquals($devSource,$productionSource)) 'Development and production pages do not share the same trace source'
$window2=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger));$records2=$main.GetField('batchTraceRecords',$private).GetValue($window2);Assert($records2.Count-eq1-and$records2[0].BatchId-eq$trace.BatchId) 'Cross-process-style new-window reload lost the persisted trace';$main.GetField('recipeCloseConfirmed',$private).SetValue($window2,$true);$window2.Close();$main.GetMethod('ReloadBatchTraceHistory',$private).Invoke($window,[object[]]@($true))|Out-Null;Assert($records.Count-eq1) 'Cross-reload trace disappeared'
$traceStore=$main.GetField('batchTraceStore',$private).GetValue($window);$traceDir=$traceStore.DirectoryPath;[IO.File]::WriteAllText((Join-Path $traceDir 'legacy.json'),'{"BatchId":"OLD-01","StartedAtUtc":"2026-08-01T00:00:00Z","Items":[{"FileName":"legacy.png","State":"OK"}]}');[IO.File]::WriteAllText((Join-Path $traceDir 'broken.json'),'{broken')
$main.GetMethod('ReloadBatchTraceHistory',$private).Invoke($window,[object[]]@($false))|Out-Null;Assert($records.Count-eq2) 'Legacy trace was not normalized or corrupt trace was not isolated';Assert(($records|Where-Object BatchId -eq 'OLD-01').OkCount-eq1) 'Legacy trace missing-field normalization failed'
$filtered=$main.GetField('filteredBatchTraceRecords',$private).GetValue($window);(F 'BatchTraceRecipeFilterTextBox').Text='S44';Pump 50;$main.GetMethod('ApplyBatchTraceFilters',$private).Invoke($window,@())|Out-Null;Assert($filtered.Count-eq1) 'Recipe filter mismatch';(F 'BatchTraceIdFilterTextBox').Text=$trace.BatchId.Substring(0,8);$main.GetMethod('ApplyBatchTraceFilters',$private).Invoke($window,@())|Out-Null;Assert($filtered.Count-eq1) 'Batch ID filter mismatch'
$csv=Join-Path $temp 'trace.csv';$traceStore.ExportCsv($csv,$filtered);$csvText=[IO.File]::ReadAllText($csv);Assert($csvText.Contains('RecipeFingerprint')-and$csvText.Contains('same.png')-and$csvText.Contains($trace.BatchId)) 'CSV export missing required fields'

# B: exact boundary classification, group stats, three managed XLDs/colors, validation, empty, ownership, old snapshots, recipe and downstream.
$tool=Tool XldLengthClassification 'S44 Length Class';$tool.Parameters.XldLengthShortMaximum=10;$tool.Parameters.XldLengthMediumMaximum=20;$xld=MultiXld ([double[]]@(5,10,15,20,30));try{$record=RunClass $tool $xld;Assert($record.ResultCode-eq'OK') 'Classification returned non-OK';Assert([int](Out $tool ShortCount)-eq2-and[int](Out $tool MediumCount)-eq2-and[int](Out $tool LongCount)-eq1) 'Threshold boundary classification was not mutually exclusive';Assert([Math]::Abs([double](Out $tool ShortTotalLength)-15)-lt.001-and[Math]::Abs([double](Out $tool MediumMeanLength)-17.5)-lt.001-and[Math]::Abs([double](Out $tool LongMaxLength)-30)-lt.001) 'Per-class statistics mismatch';[HalconDotNet.HTuple]$count=$null;[HalconDotNet.HOperatorSet]::CountObj($xld,[ref]$count);Assert($count.I-eq5) 'Input XLD ownership was modified'}finally{$xld.Dispose()}
$oldShort=Out $tool ShortXLD;$oldMedium=Out $tool MediumXLD;$oldLong=Out $tool LongXLD;$rerun=MultiXld ([double[]]@(8,18,28));try{RunClass $tool $rerun|Out-Null}finally{$rerun.Dispose()};Assert($oldShort.IsDisposed-and$oldMedium.IsDisposed-and$oldLong.IsDisposed) 'Prior three managed XLD snapshots were not disposed'
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$emptyRecord=RunClass $tool $empty;Assert($emptyRecord.ResultCode-eq'NG'-and[int](Out $tool ShortCount)-eq0-and[int](Out $tool MediumCount)-eq0-and[int](Out $tool LongCount)-eq0) 'Empty XLD semantics wrong'}finally{$empty.Dispose()}
foreach($limits in @(@(10,10),@(20,10),@([double]::NaN,20),@(10,[double]::PositiveInfinity))){$badTool=Tool XldLengthClassification 'Invalid';$badTool.Parameters.XldLengthShortMaximum=$limits[0];$badTool.Parameters.XldLengthMediumMaximum=$limits[1];$one=Contour 5;try{$rejected=$false;try{RunClass $badTool $one|Out-Null}catch{$rejected=$true};Assert $rejected 'Equal/reverse/nonfinite thresholds were accepted'}finally{$one.Dispose();$badTool.Dispose()}}
$dispose.Invoke($window,@())|Out-Null;$flow.Clear();$producer=Tool SubpixelEdgeExtraction 'Producer';$class=Tool XldLengthClassification 'Class Flow';$fit=Tool XldLineFitting 'Fit Long';$judge=Tool NumericJudge 'Judge Medium Count';$class.Parameters.XldLengthShortMaximum=10;$class.Parameters.XldLengthMediumMaximum=20;$class.SetInputBinding('XLD',$producer.ToolId,'XLD');$fit.SetInputBinding('XLD',$class.ToolId,'LongXLD');$judge.SetInputBinding('Value',$class.ToolId,'MediumCount');$judge.InputToolId=$class.ToolId;$judge.InputPortName='MediumCount';$judge.NumericLowerLimit=1;$judge.NumericUpperLimit=5;foreach($item in @($producer,$class,$fit,$judge)){$flow.Add($item)};$source=MultiXld ([double[]]@(15,30));try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($source,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$source.Dispose()};foreach($item in @($class,$fit,$judge)){$execute.Invoke($window,[object[]]@($item,'S44 chain'))|Out-Null};Assert($class.ResultCode-eq'OK'-and$fit.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Three-class XLD/Number downstream chain failed'
(F 'FlowToolList').SelectedItem=$class;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($class))|Out-Null;Assert((F 'DockXldLengthClassificationPanel').Visibility.ToString()-eq'Visible') 'Length classification dock panel not synchronized';$recipe=$capture.Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object ToolType -eq 'XldLengthClassification'|Select-Object -First 1;Assert($saved.Parameters.XldLengthShortMaximum-eq10-and$saved.Parameters.XldLengthMediumMaximum-eq20) 'Classification parameters not persisted';$main.GetMethod('RefreshResultOverlayLayers',$private).Invoke($window,@())|Out-Null;$resultLayers=$main.GetField('resultOverlayLayers',$private).GetValue($window);$layers=$resultLayers|Where-Object ToolId -eq $class.ToolId;Assert(($layers|Where-Object PortName -eq ShortXLD).HalconColor-eq'green'-and($layers|Where-Object PortName -eq MediumXLD).HalconColor-eq'yellow'-and($layers|Where-Object PortName -eq LongXLD).HalconColor-eq'red') 'Three class result-layer default colors mismatch'
$producerSnap=Out $producer XLD;$producerSnap.Dispose();$failed=$false;try{$execute.Invoke($window,[object[]]@($class,'disposed'))|Out-Null}catch{$failed=$true};Assert $failed 'Released upstream XLD was accepted'

$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
